function notify(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>{$('#toast').hidden=true;},6500);}
function mobile(value){document.body.dataset.mobileView=value;$$('[data-mobile]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mobile===value)));}
function scheduleSave(){clearTimeout(saveTimer);$('#save-status').textContent='Modifications à enregistrer…';saveTimer=setTimeout(()=>persist(false),450);}
async function persist(loud=true){clearTimeout(saveTimer);try{await saveLocal(project);$('#save-status').textContent='Enregistré sur cet appareil';if(loud)notify('Projet enregistré sur cet appareil. Pensez à télécharger une copie JSON pour le conserver ailleurs.');}catch(e){$('#save-status').textContent='Téléchargez une sauvegarde JSON';if(loud)notify(e.message);}}
function changed({geometry=false,all=false,render=true}={}){project.updatedAt=new Date().toISOString();if(all)project.rooms.forEach(r=>r.confirmed=false);else if(geometry&&room())room().confirmed=false;cache.clear();if(render)renderAll();scheduleSave();}
