function setMode(value){if(value==='draw'&&project.rooms.length>=60){notify('Le projet peut contenir 60 pièces au maximum.');return;}if(value==='hole'&&!room()){notify('Sélectionnez d’abord une pièce.');return;}if(value==='calibrate'&&!project.source){notify('Importez d’abord un fond de plan.');return;}mode=value;draft=[];board.dataset.mode=value;$$('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===value)));$('#finish-draw').hidden=!['draw','hole'].includes(value);$('#cancel-mode').hidden=value==='select'||value==='pan';$('#mode-hint').textContent={select:'Touchez une pièce pour la sélectionner. Déplacez ses angles pour la corriger.',pan:'Faites glisser pour déplacer la vue. Les boutons + et − règlent le zoom.',draw:'Placez les angles du contour intérieur, dans l’ordre. Puis « Terminer le contour ».',hole:'Tracez une zone à déduire du sol, entièrement à l’intérieur de la pièce.',calibrate:'Touchez les deux extrémités d’une cote connue, puis saisissez sa distance réelle.'}[value];if(['draw','hole','calibrate'].includes(value))mobile('plan');renderBoard();}
